/* ideabox launch animation — no dependencies, deterministic Canvas 2D. */
(() => {
  'use strict';
  const LOGO_SOURCE = 'data:image/png;base64,';
  const BOUNDS = { x: 310, y: 309, width: 641, height: 648 };
  const BASE_DURATION = 4400;
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const smooth = (a, b, v) => { const x = clamp((v - a) / (b - a)); return x * x * (3 - 2 * x); };
  const outCubic = t => 1 - Math.pow(1 - clamp(t), 3);
  const inOutCubic = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const bezier = (a, b, c, d, t) => {
    const q = 1 - t;
    return q * q * q * a + 3 * q * q * t * b + 3 * q * t * t * c + t * t * t * d;
  };
  function randomGenerator(seed) {
    return () => {
      let n = seed += 0x6D2B79F5;
      n = Math.imul(n ^ (n >>> 15), n | 1);
      n ^= n + Math.imul(n ^ (n >>> 7), n | 61);
      return ((n ^ (n >>> 14)) >>> 0) / 4294967296;
    };
  }

  class IdeaboxLaunch {
    constructor(canvas, options = {}) {
      if (!(canvas instanceof HTMLCanvasElement)) throw new TypeError('A canvas element is required.');
      this.canvas = canvas;
      this.context = canvas.getContext('2d', { alpha: false });
      if (!this.context) throw new Error('Canvas 2D is unavailable.');
      this.duration = Math.max(250, Number(options.duration) || BASE_DURATION);
      this.options = options;
      this.elapsed = 0;
      this.playing = false;
      this.completed = false;
      this.destroyed = false;
      this.loaded = false;
      this.frame = 0;
      this.motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
      this.resizeObserver = new ResizeObserver(() => this.resize());
      this.resizeObserver.observe(canvas);
      this.onVisibility = () => {
        if (document.hidden) {
          this.resumeWhenVisible = this.playing;
          this.pause();
        } else if (this.resumeWhenVisible) {
          this.resumeWhenVisible = false;
          this.play(false);
        }
      };
      this.onMotionChange = () => { if (this.motionQuery.matches) this.finish(); };
      document.addEventListener('visibilitychange', this.onVisibility);
      this.motionQuery.addEventListener('change', this.onMotionChange);
      this.ready = this.initialize();
    }

    async initialize() {
      this.logo = new Image();
      this.logo.src = this.options.logoSource || LOGO_SOURCE;
      await this.logo.decode();
      if (this.destroyed) return this;
      const sample = document.createElement('canvas');
      sample.width = BOUNDS.width;
      sample.height = BOUNDS.height;
      const sampleContext = sample.getContext('2d', { willReadFrequently: true });
      sampleContext.drawImage(this.logo, BOUNDS.x, BOUNDS.y, BOUNDS.width, BOUNDS.height, 0, 0, sample.width, sample.height);
      const { data } = sampleContext.getImageData(0, 0, sample.width, sample.height);
      const rng = randomGenerator(0x1DEAB0);
      this.particles = [];
      const step = 9;
      for (let y = 3; y < sample.height; y += step) {
        for (let x = 3; x < sample.width; x += step) {
          const sx = Math.round(x + (rng() - 0.5) * 3);
          const sy = Math.round(y + (rng() - 0.5) * 3);
          const index = (sy * sample.width + sx) * 4;
          if (data[index + 3] < 128 || data[index] < 180 || data[index + 1] < 180 || data[index + 2] < 180) continue;
          const angle = rng() * Math.PI * 2;
          const distance = 0.065 + Math.pow(rng(), 0.65) * 0.225;
          const side = rng() < 0.5 ? -1 : 1;
          this.particles.push({
            tx: (sx / sample.width - 0.5) * sample.width / sample.height,
            ty: sy / sample.height - 0.5,
            side,
            startX: side * (0.53 + rng() * 0.34),
            startY: (rng() - 0.5) * 0.63,
            impactX: (rng() - 0.5) * 0.018,
            impactY: (rng() - 0.5) * 0.026,
            burstX: Math.cos(angle) * distance,
            burstY: Math.sin(angle) * distance * 0.87,
            delay: rng() * 0.18,
            hit: 0.94 + rng() * 0.1,
            radius: 0.0008 + rng() * 0.0017,
            brightness: 0.42 + rng() * 0.58,
            curve: (rng() - 0.5) * 0.09,
            sparkle: rng(),
          });
        }
      }
      this.glow = document.createElement('canvas');
      this.glow.width = this.glow.height = 40;
      const glowContext = this.glow.getContext('2d');
      const glowGradient = glowContext.createRadialGradient(20, 20, 0, 20, 20, 20);
      glowGradient.addColorStop(0, 'rgba(255,255,255,1)');
      glowGradient.addColorStop(0.14, 'rgba(255,255,255,.75)');
      glowGradient.addColorStop(0.4, 'rgba(255,255,255,.14)');
      glowGradient.addColorStop(1, 'rgba(255,255,255,0)');
      glowContext.fillStyle = glowGradient;
      glowContext.fillRect(0, 0, 40, 40);
      this.loaded = true;
      this.resize();
      if (this.motionQuery.matches) this.finish();
      else if (this.options.autoStart !== false) this.play();
      else this.renderAt(0);
      return this;
    }

    resize() {
      if (this.destroyed) return;
      const rect = this.canvas.getBoundingClientRect();
      this.width = Math.max(1, rect.width);
      this.height = Math.max(1, rect.height);
      this.ratio = Math.min(this.options.pixelRatio || window.devicePixelRatio || 1, 2);
      this.canvas.width = Math.round(this.width * this.ratio);
      this.canvas.height = Math.round(this.height * this.ratio);
      if (this.loaded) this.renderAt(this.elapsed);
    }

    position(p, t) {
      const w = this.width;
      const s = Math.min(w, this.height);
      const logoSize = s * 0.38;
      const tx = p.tx * logoSize;
      const ty = p.ty * logoSize;
      const ix = p.impactX * s;
      const iy = p.impactY * s;
      if (t < p.hit) {
        const u = clamp((t - 0.08 - p.delay) / (p.hit - 0.08 - p.delay));
        const eased = u * u * (1.3 - 0.3 * u);
        const sx = p.startX * w;
        const sy = p.startY * s;
        return {
          x: bezier(sx, sx * 0.62, -p.side * s * 0.105, ix, eased),
          y: bezier(sy, sy * 0.72 + p.curve * s, -sy * 0.22, iy, eased),
        };
      }
      const bx = p.burstX * s;
      const by = p.burstY * s;
      if (t < 1.65) {
        const u = outCubic((t - p.hit) / (1.65 - p.hit));
        return { x: lerp(ix, bx, u), y: lerp(iy, by, u) };
      }
      const u = inOutCubic(clamp((t - 1.65) / 1.52));
      const turn = 0.36 * (1 - u);
      return {
        x: bezier(bx, bx - by * 0.68, tx + by * turn, tx, u),
        y: bezier(by, by + bx * 0.68, ty - bx * turn, ty, u),
      };
    }

    renderAt(milliseconds) {
      if (this.destroyed || !this.loaded) return;
      this.elapsed = clamp(milliseconds, 0, this.duration);
      const t = this.elapsed / this.duration * 4.4;
      const ctx = this.context;
      const w = this.width;
      const h = this.height;
      const s = Math.min(w, h);
      ctx.setTransform(this.ratio, 0, 0, this.ratio, 0, 0);
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, w, h);
      ctx.save();
      ctx.translate(w / 2, h / 2);

      // A single small impact pulse; the screen never flashes white.
      if (t > 0.88 && t < 1.5) {
        const pulse = Math.exp(-Math.pow((t - 1.025) / 0.12, 2));
        const glowSize = s * (0.06 + pulse * 0.105);
        ctx.globalAlpha = pulse * 0.8;
        ctx.drawImage(this.glow, -glowSize, -glowSize, glowSize * 2, glowSize * 2);
        if (t > 1.02) {
          const ring = clamp((t - 1.02) / 0.46);
          ctx.globalAlpha = (1 - ring) * 0.11;
          ctx.strokeStyle = '#fff';
          ctx.lineWidth = Math.max(0.6, s * 0.0007);
          ctx.beginPath();
          ctx.arc(0, 0, s * (0.026 + ring * 0.13), 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      const solid = smooth(2.88, 3.34, t);
      const visibility = smooth(0.06, 0.36, t) * (1 - solid);
      if (visibility > 0) {
        ctx.globalCompositeOperation = 'lighter';
        for (let index = 0; index < this.particles.length; index++) {
          const p = this.particles[index];
          const pos = this.position(p, t);
          const radius = p.radius * s;
          const twinkle = t < 2.7 ? 0.82 + 0.18 * Math.sin(t * 9 + p.sparkle * 17) : 1;
          const alpha = visibility * p.brightness * twinkle;
          // Sparse velocity trails make the opposing streams and the collision legible.
          if (index % 5 === 0 && t > 0.25 && t < 2.86) {
            const previous = this.position(p, Math.max(0, t - 0.032));
            ctx.globalAlpha = alpha * (t < 1.65 ? 0.34 : 0.2);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = Math.max(0.45, radius * 0.55);
            ctx.beginPath();
            ctx.moveTo(previous.x, previous.y);
            ctx.lineTo(pos.x, pos.y);
            ctx.stroke();
          }
          ctx.globalAlpha = alpha * 0.6;
          const glowSize = radius * (t < 1.65 ? 5.1 : 4.3);
          ctx.drawImage(this.glow, pos.x - glowSize, pos.y - glowSize, glowSize * 2, glowSize * 2);
          ctx.globalAlpha = alpha;
          ctx.fillStyle = '#fff';
          ctx.beginPath();
          ctx.arc(pos.x, pos.y, Math.max(0.35, radius * 0.63), 0, Math.PI * 2);
          ctx.fill();
        }
      }

      if (solid > 0) {
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = solid;
        const logoHeight = s * 0.38;
        const logoWidth = logoHeight * BOUNDS.width / BOUNDS.height;
        // Finish with the exact selected bitmap; the particle system never redraws its outline.
        ctx.drawImage(this.logo, BOUNDS.x, BOUNDS.y, BOUNDS.width, BOUNDS.height, -logoWidth / 2, -logoHeight / 2, logoWidth, logoHeight);
      }
      ctx.restore();
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
      return { time: this.elapsed, duration: this.duration, particleCount: this.particles.length, complete: this.elapsed >= this.duration };
    }

    play(restart = true) {
      if (this.destroyed || !this.loaded) return;
      if (this.motionQuery.matches) { this.finish(); return; }
      this.pause();
      if (restart) { this.elapsed = 0; this.completed = false; }
      this.playing = true;
      this.startedAt = performance.now() - this.elapsed;
      this.canvas.dispatchEvent(new CustomEvent('ideabox:start', { bubbles: true }));
      const tick = now => {
        if (!this.playing || this.destroyed) return;
        this.renderAt(now - this.startedAt);
        if (this.elapsed >= this.duration) this.finish();
        else this.frame = requestAnimationFrame(tick);
      };
      this.frame = requestAnimationFrame(tick);
    }

    pause() {
      if (this.playing) this.elapsed = Math.min(this.duration, performance.now() - this.startedAt);
      this.playing = false;
      cancelAnimationFrame(this.frame);
    }

    finish() {
      if (!this.loaded || this.destroyed) return;
      this.pause();
      this.renderAt(this.duration);
      if (!this.completed) {
        this.completed = true;
        this.canvas.dispatchEvent(new CustomEvent('ideabox:complete', { bubbles: true, detail: { duration: this.duration } }));
        this.options.onComplete?.();
      }
    }

    destroy() {
      this.pause();
      this.destroyed = true;
      this.resizeObserver.disconnect();
      document.removeEventListener('visibilitychange', this.onVisibility);
      this.motionQuery.removeEventListener('change', this.onMotionChange);
    }
  }

  window.IdeaboxLaunch = IdeaboxLaunch;
})();
